import{_ as p,a0 as o,w as d,s as r,ao as l,I as t,x as n,a1 as e,A as i}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const y=JSON.parse('{"title":"如何在 Linux 上使用网络配置工具 Netplan | LCTT x X-CMD","titleTemplate":false,"description":"如何在 Linux 上使用网络配置工具 Netplan | LCTT (201810) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何在 Linux 上使用网络配置工具 Netplan | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何在 Linux 上使用网络配置工具 Netplan | LCTT (201810) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201810/20180907 How to Use the Netplan Network Configuration Tool on Linux","title":"如何在 Linux 上使用网络配置工具 Netplan","tag":"201810","desc":""},"relativePath":"201810/20180907 How to Use the Netplan Network Configuration Tool on Linux.md","filePath":"[post].md"}'),h={name:"201810/20180907 How to Use the Netplan Network Configuration Tool on Linux.md"};function u(g,s,k,c,b,f){const a=o("Link");return d(),r("div",null,[s[25]||(s[25]=l(`<h1 id="如何在-linux-上使用网络配置工具-netplan" tabindex="-1">如何在 Linux 上使用网络配置工具 Netplan <a class="header-anchor" href="#如何在-linux-上使用网络配置工具-netplan" aria-label="Permalink to “如何在 Linux 上使用网络配置工具 Netplan”">​</a></h1><blockquote><p>netplan 是一个命令行工具，用于在某些 Linux 发行版上配置网络。</p></blockquote><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/netplan.jpg?itok=Gu_ZfNGa" alt=""></p><p>多年以来 Linux 管理员和用户们以相同的方式配置他们的网络接口。例如，如果你是 Ubuntu 用户，你能够用桌面 GUI 配置网络连接，也可以在 <code>/etc/network/interfaces</code> 文件里配置。配置相当简单且可以奏效。在文件中配置看起来就像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>auto enp10s0</span></span>
<span class="line"><span>iface enp10s0 inet static</span></span>
<span class="line"><span>address 192.168.1.162</span></span>
<span class="line"><span>netmask 255.255.255.0</span></span>
<span class="line"><span>gateway 192.168.1.100</span></span>
<span class="line"><span>dns-nameservers 1.0.0.1,1.1.1.1</span></span></code></pre></div><p>保存并关闭文件。使用命令重启网络：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo systemctl restart networking</span></span></code></pre></div><p>或者，如果你使用不带 systemd 的发行版，你可以通过老办法来重启网络：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo /etc/init.d/networking restart</span></span></code></pre></div><p>你的网络将会重新启动，新的配置将会生效。</p>`,10)),t("p",null,[s[1]||(s[1]=n("这就是多年以来的做法。但是现在，在某些发行版上（例如 Ubuntu Linux 18.04），网络的配置与控制发生了很大的变化。不需要那个 ",-1)),s[2]||(s[2]=t("code",null,"interfaces",-1)),s[3]||(s[3]=n(" 文件和 ",-1)),s[4]||(s[4]=t("code",null,"/etc/init.d/networking",-1)),s[5]||(s[5]=n(" 脚本，我们现在转向使用 ",-1)),e(a,{href:"https://netplan.io/"},{default:i(()=>[...s[0]||(s[0]=[n("Netplan",-1)])]),_:1}),s[6]||(s[6]=n("。Netplan 是一个在某些 Linux 发行版上配置网络连接的命令行工具。Netplan 使用 YAML 描述文件来配置网络接口，然后，通过这些描述为任何给定的呈现工具生成必要的配置选项。",-1))]),s[26]||(s[26]=l(`<p>我将向你展示如何在 Linux 上使用 Netplan 配置静态 IP 地址和 DHCP 地址。我会在 Ubuntu Server 18.04 上演示。有句忠告，你创建的 .yaml 文件中的缩进必须保持一致，否则将会失败。你不用为每行使用特定的缩进间距，只需保持一致就行了。</p><h3 id="新的配置文件" tabindex="-1">新的配置文件 <a class="header-anchor" href="#新的配置文件" aria-label="Permalink to “新的配置文件”">​</a></h3><p>打开终端窗口（或者通过 SSH 登录进 Ubuntu 服务器）。你会在 <code>/etc/netplan</code> 文件夹下发现 Netplan 的新配置文件。使用 <code>cd /etc/netplan</code> 命令进入到那个文件夹下。一旦进到了那个文件夹，也许你就能够看到一个文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>01-netcfg.yaml</span></span></code></pre></div><p>你可以创建一个新的文件或者是编辑默认文件。如果你打算修改默认文件，我建议你先做一个备份：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo cp /etc/netplan/01-netcfg.yaml /etc/netplan/01-netcfg.yaml.bak</span></span></code></pre></div><p>备份好后，就可以开始配置了。</p><h3 id="网络设备名称" tabindex="-1">网络设备名称 <a class="header-anchor" href="#网络设备名称" aria-label="Permalink to “网络设备名称”">​</a></h3><p>在你开始配置静态 IP 之前，你需要知道设备名称。要做到这一点，你可以使用命令 <code>ip a</code>，然后找出哪一个设备将会被用到（图 1）。</p><p><img src="https://www.linux.com/sites/lcom/files/styles/rendered_file/public/netplan_1.jpg?itok=XuIsXWbV" alt="netplan" title="netplan"></p><p><em>图 1：使用 ip a 命令找出设备名称</em></p><p>我将为 ens5 配置一个静态的 IP。</p><h3 id="配置静态-ip-地址" tabindex="-1">配置静态 IP 地址 <a class="header-anchor" href="#配置静态-ip-地址" aria-label="Permalink to “配置静态 IP 地址”">​</a></h3><p>使用命令打开原来的 .yaml 文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo nano /etc/netplan/01-netcfg.yaml</span></span></code></pre></div><p>文件的布局看起来就像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>network:</span></span>
<span class="line"><span>    Version: 2</span></span>
<span class="line"><span>    Renderer: networkd</span></span>
<span class="line"><span>    ethernets:</span></span>
<span class="line"><span>       DEVICE_NAME:</span></span>
<span class="line"><span>          Dhcp4: yes/no</span></span>
<span class="line"><span>          Addresses: [IP/NETMASK]</span></span>
<span class="line"><span>          Gateway: GATEWAY</span></span>
<span class="line"><span>          Nameservers:</span></span>
<span class="line"><span>             Addresses: [NAMESERVER, NAMESERVER]</span></span></code></pre></div><p>其中：</p><ul><li><code>DEVICE_NAME</code> 是需要配置设备的实际名称。</li><li><code>yes</code>/<code>no</code> 代表是否启用 dhcp4。</li><li><code>IP</code> 是设备的 IP 地址。</li><li><code>NETMASK</code> 是 IP 地址的掩码。</li><li><code>GATEWAY</code> 是网关的地址。</li><li><code>NAMESERVER</code> 是由逗号分开的 DNS 服务器列表。</li></ul><p>这是一份 .yaml 文件的样例：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>network:</span></span>
<span class="line"><span>    version: 2</span></span>
<span class="line"><span>    renderer: networkd</span></span>
<span class="line"><span>    ethernets:</span></span>
<span class="line"><span>       ens5:</span></span>
<span class="line"><span>       dhcp4: no</span></span>
<span class="line"><span>       addresses: [192.168.1.230/24]</span></span>
<span class="line"><span>       gateway4: 192.168.1.254</span></span>
<span class="line"><span>       nameservers:</span></span>
<span class="line"><span>          addresses: [8.8.4.4,8.8.8.8]</span></span></code></pre></div><p>编辑上面的文件以达到你想要的效果。保存并关闭文件。</p><p>注意，掩码已经不用再配置为 <code>255.255.255.0</code> 这种形式。取而代之的是，掩码已被添加进了 IP 地址中。</p><h3 id="测试配置" tabindex="-1">测试配置 <a class="header-anchor" href="#测试配置" aria-label="Permalink to “测试配置”">​</a></h3><p>在应用改变之前，让我们测试一下配置。为此，使用命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo netplan try</span></span></code></pre></div><p>上面的命令会在应用配置之前验证其是否有效。如果成功，你就会看到配置被接受。换句话说，Netplan 会尝试将新的配置应用到运行的系统上。如果新的配置失败了，Netplan 会自动地恢复到之前使用的配置。成功后，新的配置就会被使用。</p><h3 id="应用新的配置" tabindex="-1">应用新的配置 <a class="header-anchor" href="#应用新的配置" aria-label="Permalink to “应用新的配置”">​</a></h3><p>如果你确信配置文件没有问题，你就可以跳过测试环节并且直接使用新的配置。它的命令是：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo netplan apply</span></span></code></pre></div><p>此时，你可以使用 ip a 看看新的地址是否正确。</p><h3 id="配置-dhcp" tabindex="-1">配置 DHCP <a class="header-anchor" href="#配置-dhcp" aria-label="Permalink to “配置 DHCP”">​</a></h3><p>虽然你可能不会配置 DHCP 服务，但通常还是知道比较好。例如，你也许不知道网络上当前可用的静态 IP 地址是多少。你可以为设备配置 DHCP，获取到 IP 地址，然后将那个地址重新配置为静态地址。</p><p>在 Netplan 上使用 DHCP，配置文件看起来就像这样：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>network:</span></span>
<span class="line"><span>    version: 2</span></span>
<span class="line"><span>    renderer: networkd</span></span>
<span class="line"><span>    ethernets:</span></span>
<span class="line"><span>       ens5:</span></span>
<span class="line"><span>       Addresses: []</span></span>
<span class="line"><span>       dhcp4: true</span></span>
<span class="line"><span>       optional: true</span></span></code></pre></div><p>保存并退出。用下面命令来测试文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo netplan try</span></span></code></pre></div><p>Netplan 应该会成功配置 DHCP 服务。这时你可以使用 <code>ip a</code> 命令得到动态分配的地址，然后重新配置静态地址。或者，你可以直接使用 DHCP 分配的地址（但看看这是一个服务器，你可能不想这样做）。</p><p>也许你有不只一个的网络接口，你可以命名第二个 .yaml 文件为 <code>02-netcfg.yaml</code> 。Netplan 会按照数字顺序应用配置文件，因此 01 会在 02 之前使用。根据你的需要创建多个配置文件。</p><h3 id="就是这些了" tabindex="-1">就是这些了 <a class="header-anchor" href="#就是这些了" aria-label="Permalink to “就是这些了”">​</a></h3><p>不管怎样，那些就是所有关于使用 Netplan 的东西了。虽然它对于我们习惯性的配置网络地址来说是一个相当大的改变，但并不是所有人都用的惯。但这种配置方式值得一提……因此你会适应的。</p>`,41)),t("p",null,[s[8]||(s[8]=n("在 Linux Foundation 和 edX 上通过 ",-1)),e(a,{href:"https://training.linuxfoundation.org/linux-courses/system-administration-training/introduction-to-linux"},{default:i(()=>[...s[7]||(s[7]=[n("“Introduction to Linux”",-1)])]),_:1}),s[9]||(s[9]=n(" 课程学习更多关于 Linux 的内容。",-1))]),s[27]||(s[27]=t("hr",null,null,-1)),t("p",null,[s[11]||(s[11]=n("via: ",-1)),e(a,{href:"https://www.linux.com/learn/intro-to-linux/2018/9/how-use-netplan-network-configuration-tool-linux"},{default:i(()=>[...s[10]||(s[10]=[n("https://www.linux.com/learn/intro-to-linux/2018/9/how-use-netplan-network-configuration-tool-linux",-1)])]),_:1})]),t("p",null,[s[16]||(s[16]=n("作者：",-1)),e(a,{href:"https://www.linux.com/users/jlwallen"},{default:i(()=>[...s[12]||(s[12]=[n("Jack Wallen",-1)])]),_:1}),s[17]||(s[17]=n(" 选题：",-1)),e(a,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[13]||(s[13]=[n("lujun9972",-1)])]),_:1}),s[18]||(s[18]=n(" 译者：",-1)),e(a,{href:"https://github.com/LuuMing"},{default:i(()=>[...s[14]||(s[14]=[n("LuuMing",-1)])]),_:1}),s[19]||(s[19]=n(" 校对：",-1)),e(a,{href:"https://github.com/wxy"},{default:i(()=>[...s[15]||(s[15]=[n("wxy",-1)])]),_:1})]),t("p",null,[s[22]||(s[22]=n("本文由 ",-1)),e(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[20]||(s[20]=[n("LCTT",-1)])]),_:1}),s[23]||(s[23]=n(" 原创编译，",-1)),e(a,{href:"https://linux.cn/"},{default:i(()=>[...s[21]||(s[21]=[n("Linux中国",-1)])]),_:1}),s[24]||(s[24]=n(" 荣誉推出",-1))])])}const C=p(h,[["render",u]]);export{y as __pageData,C as default};
